int count = 0;
for (RT::Cell_circulator circ = rt.cells_begin(h), done = rt.cells_end(); circ != done; ++circ) {
    RT::Cell_handle neighbor = *circ;
    if (neighbor->index() < h->index()) {  // Avoid double-counting edges
        for (int i = 0; i < 4; ++i) {
            RT::Vertex_handle v1 = rt.vertex(h, i);
            RT::Vertex_handle v2 = rt.vertex(neighbor, (i + 1) % 4);
            double dx = v1->x() - v2->x();
            double dy = v1->y() - v2->y();
            double dz = v1->z() - v2->z();
            double squared_length = dx*dx + dy*dy + dz*dz;
            if (squared_length > threshold) {
                ++count;
            }
        }
    }
}
return count;
// END_CODE

